using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "AbyssalShatterCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Cellarius/AbyssalShatterCustomDescription", order = 0)]
public class AbyssalShatterCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		AbyssalShatterAction abyssalShatterAction = battleAction as AbyssalShatterAction;
		string actionDescription = abyssalShatterAction.PurifyAction.GetActionDescription(GetAmountWithoutEquation(amountModified), GetBonusAmountWithoutEquation(amountModified));
		string actionDescription2 = abyssalShatterAction.LoseHeartAction.GetActionDescription(EffectsValues.NO_VALUE);
		return actionDescription + "\n" + Smart.Format(GetRawLocalizedDescription(abyssalShatterAction), amountModified) + "\n" + actionDescription2;
	}
}
